mapper.select:
SELECT PRODUCT_SEQ , NAME , DESCRIPTION , PRICE , IMAGE_URL , STOCK , CATEGORY_TYPE , STATUS , DISCOUNT_RATE , SELL_COUNT , RATING , TAGS , BRAND , CREATE_DATE , UPDATE_DATE FROM TB_PRODUCT
AND CATEGORY_TYPE = #{categoryType}
AND STATUS = #{status}
AND (NAME LIKE CONCAT('%', #{searchKeyword}, '%') OR DESCRIPTION LIKE CONCAT('%', #{searchKeyword}, '%') OR TAGS LIKE CONCAT('%', #{searchKeyword}, '%'))
ORDER BY ${sortBy} ${sortOrder}
ORDER BY CREATE_DATE DESC
LIMIT #{limit}
OFFSET #{offset}

mapper.update:
UPDATE TB_PRODUCT
SET NAME = #{name}
    , DESCRIPTION = #{description}
    , PRICE = #{price}
    , IMAGE_URL = #{imageUrl}
    , STOCK = #{stock}
    , CATEGORY_TYPE = #{categoryType}
    , STATUS = #{status}
    , DISCOUNT_RATE = #{discountRate}
    , SELL_COUNT = #{sellCount}
    , RATING = #{rating}
    , TAGS = #{tags}
    , BRAND = #{brand}
    , UPDATE_DATE = NOW()
WHERE PRODUCT_SEQ = #{productSeq}

